fn extract_rear_chars(l: &Vec<Vec<char>>) -> Vec<char> {
    // Pre‐allocate the result vector to have the same length as the input
    let mut result = Vec::with_capacity(l.len());
    // For each inner vector, take its last character
    for v in l {
        // We can safely unwrap() because the problem guarantees each inner vector is non‐empty
        result.push(*v.last().unwrap());
    }
    result
}

